// a spinning component for fun, for more info check the 'component' example
function spin(speed = 1200) {
    let spinning = false;
    return {
        require: ["rotate"],
        update() {
            if (!spinning) {
                return;
            }
            this.angle -= speed * dt();
            if (this.angle <= -360) {
                spinning = false;
                this.angle = 0;
            }
        },
        spin() {
            spinning = true;
        },
    };
}

