function rayCastShapes(origin, direction) {
    let minHit;
    const shapes = get("shape");
    shapes.forEach(s => {
        const shape = s.getShape();
        const hit = shape.raycast(origin, direction);
        if (hit) {
            if (minHit) {
                if (hit.fraction < minHit.fraction) {
                    minHit = hit;
                }
            }
            else {
                minHit = hit;
            }
        }
    });
    return minHit;
}

