function spin() {
    let spinning = false;
    return {
        id: "spin",
        update() {
            if (spinning) {
                this.angle += 1200 * dt();
                if (this.angle >= 360) {
                    this.angle = 0;
                    spinning = false;
                }
            }
        },
        spin() {
            spinning = true;
        },
    };
}

function interact() {
    let interacted = false;
    for (const col of player.getCollisions()) {
        const c = col.target;
        if (c.is("chest")) {
            if (c.opened) {
                c.play("close");
                c.opened = false;
            }
            else {
                c.play("open");
                c.opened = true;
            }
            interacted = true;
        }
    }
    if (!interacted) {
        sword.spin();
    }
}

